-- SQL identities are synthetic; this is NOT GoTrue/PostgREST authentication.
BEGIN;
GRANT USAGE ON SCHEMA community_test TO service_role;
GRANT SELECT ON community_test.ids TO service_role;
CREATE TEMP TABLE progression_original AS SELECT community_test.snapshot() AS value;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),0);
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'xp')='0','new collective account starts at zero');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='1','initial level is one');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'earning_enabled')='false','source defaults off');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),gen_random_uuid())$q$,'42501');
SELECT community_test.denied($q$SELECT * FROM security_private.community_verified_activities$q$,'42501');
SELECT community_test.denied('SELECT * FROM public.community_xp_accounts','42501');
SELECT community_test.denied('SELECT * FROM public.community_xp_ledger','42501');
SELECT community_test.denied($q$INSERT INTO public.community_xp_accounts VALUES(community_test.id('a'),999999,1,now())$q$,'42501');
SELECT community_test.denied($q$SELECT public.get_community_progression(community_test.id('b'))$q$,'42501');
SELECT community_test.actor(7);
SELECT community_test.denied($q$SELECT public.get_community_progression(community_test.id('a'))$q$,'42501');
SELECT community_test.actor(5);
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='1','ordinary member may see collective level');
SELECT community_test.denied($q$SELECT public.list_community_xp_history(community_test.id('a'))$q$,'42501');
SELECT community_test.actor(3);
SELECT community_test.denied($q$SELECT public.list_community_xp_history(community_test.id('a'))$q$,'42501');
SELECT community_test.actor(1);
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),true);
SELECT community_test.actor(2);
SELECT community_test.assert(public.list_community_xp_history(community_test.id('a'))='[]','delegated manager sees history');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),gen_random_uuid())$q$,'42501');
RESET ROLE;
SELECT community_test.assert(security_private.community_xp_allowance(100,350,350,0,350,350)=0,'weekly ceiling independent of unused daily allowance');
SELECT community_test.assert(security_private.community_xp_allowance(100,350,350,0,300,300)=50,'partial weekly allowance independent of daily cap');
SELECT community_test.assert(security_private.community_xp_allowance(100,350,350,350,350,350)=0,'no negative XP at cap');
SELECT community_test.assert(security_private.community_xp_allowance(100,350,350,0,0,1000000000000)=0,'numeric safety ceiling never reduces permanent XP');
INSERT INTO security_private.community_verified_activities(id,server_id,source,evidence_key,expires_at)
SELECT ('d4000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,community_test.id('a'),'backend_verified_activity',gen_random_uuid(),clock_timestamp()+interval '1 hour' FROM generate_series(1,15)n;
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000001')$q$,'42501','community_xp_source_disabled');
UPDATE security_private.community_xp_policy SET enabled=true,activity_xp=100,daily_cap=250,weekly_cap=350;
SELECT community_test.assert((SELECT count(*)=1 FROM security_private.community_xp_policy_audit),'policy changes audited');
SET LOCAL ROLE service_role;
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000001');
SELECT community_test.assert((public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000001')->>'replayed')='true','idempotent replay');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('b'),'d4000000-0000-0000-0000-000000000002')$q$,'22023','community_activity_unverified');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),gen_random_uuid())$q$,'22023','community_activity_unverified');
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000002');
SELECT community_test.assert((public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000003')->>'awarded_xp')='50','partial daily cap');
SELECT community_test.assert((public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000004')->>'outcome')='capped','cap is terminal auditable outcome');
RESET ROLE;
SELECT community_test.assert((SELECT xp=250 FROM public.community_xp_accounts),'daily cap respected');
SELECT community_test.assert((SELECT count(*)=4 FROM public.community_xp_ledger),'replay not double logged');
SELECT community_test.denied($q$UPDATE public.community_xp_ledger SET awarded_xp=1$q$,'23514','community_xp_immutable');
SELECT community_test.denied($q$DELETE FROM public.community_xp_ledger$q$,'23514','community_xp_immutable');
SELECT community_test.denied($q$UPDATE security_private.community_xp_curves SET base_xp=200$q$,'23514','community_xp_immutable');
-- Increase daily ceiling, keep weekly ceiling to exercise independent weekly cap.
UPDATE security_private.community_xp_policy SET daily_cap=350;
SELECT community_test.assert((public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000005')->>'awarded_xp')='100','weekly remaining');
SELECT community_test.assert((public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000006')->>'awarded_xp')='0','weekly cap');
UPDATE security_private.community_xp_policy SET daily_cap=10000,weekly_cap=10000,activity_xp=1000;
SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000007');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='2','curve crosses 1000 XP threshold');
INSERT INTO security_private.community_xp_curves VALUES(2,2000,200,DEFAULT);
UPDATE security_private.community_xp_policy SET curve_version=2;
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'curve_version')='1','existing curve pinned, no downgrade');
SAVEPOINT ledger_atomic;
CREATE FUNCTION community_test.fail_xp_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test_ledger_failure'; END $$;
CREATE TRIGGER test_ledger_failure BEFORE INSERT ON public.community_xp_ledger FOR EACH ROW EXECUTE FUNCTION community_test.fail_xp_ledger();
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000008')$q$,'P0001','test_ledger_failure');
SELECT community_test.assert((SELECT xp=1350 FROM public.community_xp_accounts),'ledger failure rolls back XP');
ROLLBACK TO SAVEPOINT ledger_atomic;
-- Actual RLS denial even if a future migration accidentally grants SELECT.
GRANT SELECT ON public.community_xp_accounts,public.community_xp_ledger TO authenticated;
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_xp_accounts),'RLS has no direct row policy');
SELECT community_test.assert(NOT EXISTS(SELECT FROM public.community_xp_ledger),'ledger RLS denies direct rows');
SELECT community_test.assert(jsonb_array_length(public.list_community_xp_history(community_test.id('a'),NULL,2))=2,'bounded history');
SELECT community_test.assert(NOT(public.list_community_xp_history(community_test.id('a'))->0 ? 'activity_id'),'private evidence not in projection');
SELECT community_test.denied($q$SELECT public.list_community_xp_history(community_test.id('a'),NULL,51)$q$,'22023');
SELECT public.set_community_role_permission(community_test.id('a'),community_test.id('delegate-role'),false);
SELECT community_test.actor(2);
SELECT community_test.denied($q$SELECT public.list_community_xp_history(community_test.id('a'))$q$,'42501');
SELECT community_test.actor(1);
SELECT public.disable_server_community(community_test.id('a'),1);
SELECT community_test.denied($q$SELECT public.get_community_progression(community_test.id('a'))$q$,'42501');
RESET ROLE;
SELECT community_test.assert((SELECT xp=1350 FROM public.community_xp_accounts),'disabled state retained');
SELECT community_test.denied($q$SELECT public.consume_verified_community_activity(community_test.id('a'),'d4000000-0000-0000-0000-000000000008')$q$,'42501','community_progression_disabled');
SET LOCAL ROLE authenticated;
SELECT community_test.actor(1);
SELECT public.save_server_community(community_test.id('a'),community_test.payload('a'),2);
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'xp')='1350','reactivation preserves XP');
RESET ROLE;
SAVEPOINT curve_boundaries;
UPDATE public.community_xp_accounts SET xp=1000 WHERE server_id=community_test.id('a');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='2','exact first threshold');
UPDATE public.community_xp_accounts SET xp=2499 WHERE server_id=community_test.id('a');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='2','one below next threshold');
UPDATE public.community_xp_accounts SET xp=2500 WHERE server_id=community_test.id('a');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='3','exact second threshold');
INSERT INTO security_private.community_xp_curves VALUES(3,100,0,DEFAULT);
UPDATE public.community_xp_accounts SET xp=1000000000000,curve_version=3 WHERE server_id=community_test.id('a');
SELECT community_test.assert((public.get_community_progression(community_test.id('a'))->>'level')='10000000001','large linear curve is bounded search, not truncated level loop');
ROLLBACK TO SAVEPOINT curve_boundaries;
-- Enough rows to cross decimal cursor boundaries; must sort numerically.
SELECT public.consume_verified_community_activity(community_test.id('a'),('d4000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid) FROM generate_series(9,15)n;
SELECT community_test.assert((public.list_community_xp_history(community_test.id('a'))->0->>'id')::bigint=(SELECT max(id) FROM public.community_xp_ledger),'history order uses numeric bigint, not lexicographic strings');
SELECT community_test.assert((public.list_community_xp_history(community_test.id('a'),(public.list_community_xp_history(community_test.id('a'),NULL,2)->1->>'id')::bigint,2)->0->>'id')::bigint < (public.list_community_xp_history(community_test.id('a'),NULL,2)->1->>'id')::bigint,'cursor excludes previously delivered rows');
SAVEPOINT banned_visibility;
INSERT INTO public.server_bans(server_id,user_id,banned_by,reason) VALUES(community_test.id('a'),community_test.user_id(5),community_test.user_id(1),'Synthetic test');
SET LOCAL ROLE authenticated;
SELECT community_test.actor(5);
SELECT community_test.denied($q$SELECT public.get_community_progression(community_test.id('a'))$q$,'42501');
RESET ROLE;
ROLLBACK TO SAVEPOINT banned_visibility;
-- Synthetic expired fact; no browser can insert it.
INSERT INTO security_private.community_verified_activities VALUES(gen_random_uuid(),community_test.id('a'),'backend_verified_activity',gen_random_uuid(),clock_timestamp()-interval '2 hours',clock_timestamp()-interval '1 hour');
SELECT community_test.denied(format('SELECT public.consume_verified_community_activity(%L,%L)',community_test.id('a'),(SELECT id FROM security_private.community_verified_activities WHERE expires_at<clock_timestamp() LIMIT 1)),'22023','community_activity_expired');
SET LOCAL ROLE anon;
SELECT community_test.denied($q$SELECT public.get_community_progression(community_test.id('a'))$q$,'42501');
RESET ROLE;
-- Only community settings/roles were intentionally changed in this suite.
SELECT community_test.assert((community_test.snapshot()->'xp')=(SELECT value->'xp' FROM progression_original),'individual XP untouched');
SELECT community_test.assert((community_test.snapshot()->'messages')=(SELECT value->'messages' FROM progression_original),'messages untouched');
SELECT community_test.assert((community_test.snapshot()->'badges')=(SELECT value->'badges' FROM progression_original),'badges untouched');
ROLLBACK;
